// Des: DOM extractor: messages and chat rows with click rects
// Flo: registry selectors > build one JS text > Runtime.evaluate > parse json > Msg and Cand lists
// I/O: Conn + Ext (caller) > Msg list, Cand list (name, unread, stranger, group, click point), rect centers
// ===================================================================
const std = @import("std"); const cdp = @import("nt-cdpz-sock.zig"); const snap = @import("ru-page-snap.zig"); const lab = @import("cf-labl-load.zig");
pub const Msg = struct { id: []const u8 = "", dir: []const u8 = "", kind: []const u8 = "text", text: []const u8 = "", time: []const u8 = "", quote: []const u8 = "", failed: []const u8 = "" };
pub const Cand = struct { name: []const u8 = "", unre: bool = false, stran: bool = false, group: bool = false, x: f64 = 0, y: f64 = 0, idx: u32 = 0 };
fn q(aren: std.mem.Allocator, txt: []const u8) ![]u8 { return std.json.Stringify.valueAlloc(aren, txt, .{}); }
fn atr(aren: std.mem.Allocator, name: []const u8, fall: []const u8) ![]u8 { if (name.len == 0) return std.fmt.allocPrint(aren, "{s}", .{fall}); return std.fmt.allocPrint(aren, "e.getAttribute({s})||{s}", .{ try q(aren, name), fall }); }
pub fn msgJs(aren: std.mem.Allocator, ext: lab.Ext) ![]u8 { return std.fmt.allocPrint(aren, "JSON.stringify(Array.from(document.querySelectorAll({s})).map(function(e){{return {{id:{s},dir:{s},kind:{s},time:{s},quote:{s},failed:{s},text:(e.getAttribute('aria-label')||e.textContent||'')}}}}))", .{ try q(aren, ext.msg_sel), try atr(aren, ext.id_atr, "''"), try atr(aren, ext.dir_atr, "''"), try atr(aren, ext.kind_atr, "'text'"), try atr(aren, ext.time_atr, "''"), try atr(aren, ext.quot_atr, "''"), try atr(aren, ext.fail_atr, "''") }); }
pub fn chatJs(aren: std.mem.Allocator, ext: lab.Ext) ![]u8 { return std.fmt.allocPrint(aren, "JSON.stringify(Array.from(document.querySelectorAll({s})).map(function(e,i){{var r=e.getBoundingClientRect();return {{i:i,name:{s},unre:Number({s})>0,stran:({s})==='0',group:({s})==='1',x:r.left+r.width/2,y:r.top+r.height/2,h:r.height}}}}).filter(function(c){{return c.h>0}}))", .{ try q(aren, ext.chat_sel), try atr(aren, ext.chat_nam_atr, "e.textContent"), try atr(aren, ext.chat_unr_atr, "'0'"), try atr(aren, ext.chat_fri_atr, "'1'"), try atr(aren, ext.chat_grp_atr, "'0'") }); }
const Rawc = struct { name: []const u8 = "", unre: bool = false, stran: bool = false, group: bool = false, x: f64 = 0, y: f64 = 0, h: f64 = 0, i: u32 = 0 };
pub fn msgsDom(aren: std.mem.Allocator, conn: *cdp.Conn, ext: lab.Ext) ![]Msg { if (ext.msg_sel.len == 0) return error.NoElem; const txt = try snap.evalStr(aren, conn, try msgJs(aren, ext)); if (txt.len == 0) return &.{}; return std.json.parseFromSliceLeaky([]Msg, aren, txt, .{ .ignore_unknown_fields = true, .allocate = .alloc_always }) catch return error.CdpError; }
pub fn chatsDom(aren: std.mem.Allocator, conn: *cdp.Conn, ext: lab.Ext) ![]Cand { if (ext.chat_sel.len == 0) return error.NoElem; const txt = try snap.evalStr(aren, conn, try chatJs(aren, ext)); if (txt.len == 0) return &.{}; const raw = std.json.parseFromSliceLeaky([]Rawc, aren, txt, .{ .ignore_unknown_fields = true, .allocate = .alloc_always }) catch return error.CdpError; var out: std.ArrayList(Cand) = .empty; for (raw) |row| try out.append(aren, .{ .name = row.name, .unre = row.unre, .stran = row.stran, .group = row.group, .x = row.x, .y = row.y, .idx = row.i }); return out.items; }
pub fn rectCenter(aren: std.mem.Allocator, conn: *cdp.Conn, sel: []const u8) !?snap.Pt { if (sel.len == 0) return null; const js = try std.fmt.allocPrint(aren, "(function(){{var e=document.querySelector({s});if(!e)return '';var r=e.getBoundingClientRect();return Math.round(r.left+r.width/2)+','+Math.round(r.top+r.height/2)}})()", .{try q(aren, sel)}); const txt = try snap.evalStr(aren, conn, js); if (txt.len == 0) return null; var itr = std.mem.splitScalar(u8, txt, ','); const xs = itr.next() orelse return null; const ys = itr.next() orelse return null; return .{ .x = @floatFromInt(std.fmt.parseInt(i32, xs, 10) catch return null), .y = @floatFromInt(std.fmt.parseInt(i32, ys, 10) catch return null) }; }
pub fn revealNth(aren: std.mem.Allocator, conn: *cdp.Conn, sel: []const u8, idx: u32) !?snap.Pt { const js = try std.fmt.allocPrint(aren, "(function(){{var e=document.querySelectorAll({s})[{d}];if(!e)return '';e.scrollIntoView({{block:'center'}});var r=e.getBoundingClientRect();return Math.round(r.left+r.width/2)+','+Math.round(r.top+r.height/2)}})()", .{ try q(aren, sel), idx }); const txt = try snap.evalStr(aren, conn, js); if (txt.len == 0) return null; var itr = std.mem.splitScalar(u8, txt, ','); const xs = itr.next() orelse return null; const ys = itr.next() orelse return null; return .{ .x = @floatFromInt(std.fmt.parseInt(i32, xs, 10) catch return null), .y = @floatFromInt(std.fmt.parseInt(i32, ys, 10) catch return null) }; }
pub fn countSel(aren: std.mem.Allocator, conn: *cdp.Conn, sel: []const u8) !u32 { const js = try std.fmt.allocPrint(aren, "String(document.querySelectorAll({s}).length)", .{try q(aren, sel)}); return std.fmt.parseInt(u32, try snap.evalStr(aren, conn, js), 10) catch 0; }
